// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./SingleProjectContract.sol";

/**
 * @title ProjectFactory
 * @dev Фабрика для создания отдельных контрактов проектов
 * 
 * Этот контракт создает новый экземпляр SingleProjectContract для каждого проекта,
 * обеспечивая полную изоляцию между проектами
 */
contract ProjectFactory {
    // Владелец фабрики
    address public owner;
    
    // Счетчик проектов
    uint256 public projectCount;
    
    // Маппинг ID проекта => адрес контракта проекта
    mapping(uint256 => address) public projects;
    
    // Маппинг адрес контракта => ID проекта
    mapping(address => uint256) public projectIds;
    
    // События
    event ProjectCreated(uint256 indexed projectId, address indexed projectContract, string name, uint256 targetAmount);
    
    constructor() {
        owner = msg.sender;
        projectCount = 0;
    }
    
    /**
     * @dev Создает новый проект (новый контракт)
     * @param _projectName Название проекта
     * @param _targetAmount Целевая сумма для сбора в wei
     * @param _projectWallet Адрес кошелька, на который будут выводиться средства проекта
     * @return projectId ID созданного проекта
     * @return projectAddress Адрес созданного контракта проекта
     */
    function createProject(
        string memory _projectName,
        uint256 _targetAmount,
        address _projectWallet
    ) public returns (uint256 projectId, address projectAddress) {
        projectCount++;
        projectId = projectCount;
        
        // Создаем новый контракт проекта
        SingleProjectContract newProject = new SingleProjectContract(
            _projectName,
            _targetAmount,
            _projectWallet,
            owner
        );
        
        projectAddress = address(newProject);
        projects[projectId] = projectAddress;
        projectIds[projectAddress] = projectId;
        
        emit ProjectCreated(projectId, projectAddress, _projectName, _targetAmount);
        
        return (projectId, projectAddress);
    }
    
    /**
     * @dev Возвращает адрес контракта проекта по ID
     * @param _projectId ID проекта
     * @return Адрес контракта проекта
     */
    function getProjectAddress(uint256 _projectId) public view returns (address) {
        require(projects[_projectId] != address(0), "Project does not exist");
        return projects[_projectId];
    }
    
    /**
     * @dev Возвращает ID проекта по адресу контракта
     * @param _projectAddress Адрес контракта проекта
     * @return ID проекта
     */
    function getProjectId(address _projectAddress) public view returns (uint256) {
        uint256 id = projectIds[_projectAddress];
        require(id > 0, "Project contract not found");
        return id;
    }
    
    /**
     * @dev Проверяет, существует ли проект
     * @param _projectId ID проекта
     * @return true, если проект существует
     */
    function projectExists(uint256 _projectId) public view returns (bool) {
        return projects[_projectId] != address(0);
    }
}

